def walk(p, depth):
    out = []
    if depth > 3:
        return out
    for e in repo.list(p):
        path = (p.rstrip("/") + "/" + e) if p != "." else e
        if e.endswith("/"):
            out.extend(walk(path.rstrip("/"), depth + 1))
        else:
            out.append(path)
    return out

files = walk(".", 0)
contents = {}
for f in files:
    contents[f] = repo.read(f, missing_ok=True)
result({"files": files, "contents": contents})

